/* eslint-disable no-unused-vars */
import React, { useRef, useContext } from "react";
import { Container, Typography, TextField } from "@material-ui/core";
import { makeStyles } from "@material-ui/core/styles";
import { TextDecrypt } from "../content/TextDecrypt";
import Swal from 'sweetalert2';
import { ThemeContext } from '../theme/ThemeProvider';

import emailjs from '@emailjs/browser';

import './Contact.css';

const useStyles = makeStyles((theme) => ({
  main: {
    maxWidth: '100vw',
    marginTop: '3em',
    marginBottom: "3em",
  },
  form: {
    width: '100%',
  },
  formfield: {
    width: '100%',
    marginBottom: '2rem',
  },
}));

export const Contact = () => {
  const classes = useStyles();
  const greetings = "Say hello.";
  const { theme } = useContext(ThemeContext);
  const form = useRef();

  const sendEmail = (e) => {
    e.preventDefault();

    // Tentukan warna popup berdasarkan tema yang aktif
    const popupBackgroundColor = theme === 'dark' ? 'rgba(26, 40, 46, 0.9)' : 'rgba(244, 244, 244, 0.9)';
    const popupColor = theme === 'dark' ? '#FFFFFF' : '#333333';
    
    // Tampilkan popup "Loading"
    Swal.fire({
      title: 'Mengirim Pesan...',
      text: 'Mohon tunggu sebentar.',
      allowOutsideClick: false,
      didOpen: () => {
        Swal.showLoading();
      },
      background: popupBackgroundColor,
      color: popupColor,
      backdrop: `
        rgba(0,0,0,0.4)
        blur(10px)
      `,
    });

    // Kirim email menggunakan EmailJS
    emailjs.sendForm('service_8rim5bs', 'template_lox4isr', form.current, '3bqbE7_GrMsaOWCAm')
      .then((result) => {
          // Jika sukses, tampilkan popup sukses
          Swal.fire({
            position: 'center',
            icon: 'success',
            title: 'Pesan Terkirim!',
            text: 'Terima kasih, saya akan segera membalasnya.',
            background: popupBackgroundColor,
            color: popupColor,
            iconColor: '#00bfbf',
            timer: 2500,
            timerProgressBar: true,
            showConfirmButton: false,
          });
          e.target.reset(); // Reset form hanya jika sukses
      }, (error) => {
          // Jika gagal, tampilkan popup error
          Swal.fire({
            icon: 'error',
            title: 'Oops... Gagal Mengirim',
            text: 'Terjadi kesalahan pada server. Coba lagi nanti.',
            background: popupBackgroundColor,
            color: popupColor,
          });
      });
  };

  return (
    <section id="contact">
      <Container component="main" className={classes.main} maxWidth="md">
        <div className="contact">
          <div className="_form_wrapper">
            <form ref={form} onSubmit={sendEmail} className={classes.form}>
              <TextField
                id="outlined-name-input"
                label="Nama"
                type="text"
                size="small"
                variant="filled"
                name="name"
                required
                className={classes.formfield}
              />
              <TextField
                id="outlined-email-input" // ID diubah agar unik
                label="Email"
                type="email"
                size="small"
                variant="filled"
                name="email"
                required
                className={classes.formfield}
              />
              <TextField
                id="outlined-message-input" // ID diubah agar unik
                label="Pesan"
                type="textarea"
                size="small"
                multiline
                minRows={5}
                variant="filled"
                name="message"
                required
                className={classes.formfield}
              />
              <button type="submit" value="Send" className="submit-btn">
                <i className="fas fa-terminal"></i>
                <Typography component='span'> Kirim pesan.</Typography>
              </button>
            </form>
          </div>
          <h1 className="contact_msg">
            <TextDecrypt text={greetings}/>
          </h1>
        </div>
      </Container>
    </section>
  );
};